/* A website's password page and the contact inbox. site_access keeps, per creator, whether their published website asks visitors for a password, a salted scrypt hash of that password (never the password itself) and a version that changes with every new password, so a visitor's pass made for the old one stops working. Server only: row level security on, no policies, nothing granted to visitors or signed in users; the creator changes it through Website Settings, which checks they own the site. site_contact_messages gets read_at, so the Messages tab in Emails can say which messages are new; the creator marks them read through the server, which checks the message is theirs. Until this runs, no website asks for a password and every message reads as read. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.site_access ( creator_id uuid PRIMARY KEY REFERENCES public.creators(id) ON DELETE CASCADE, password_enabled boolean NOT NULL DEFAULT false, password_hash text, password_version integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT site_access_hash_shape CHECK (password_hash IS NULL OR (char_length(password_hash) BETWEEN 40 AND 300 AND password_hash LIKE 'scrypt$%')), CONSTRAINT site_access_on_needs_hash CHECK (NOT password_enabled OR password_hash IS NOT NULL) );
CREATE INDEX IF NOT EXISTS site_access_enabled ON public.site_access (creator_id) WHERE password_enabled;
ALTER TABLE public.site_access ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.site_access FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.site_access TO service_role;
DO $$ BEGIN IF to_regclass('public.site_contact_messages') IS NOT NULL THEN ALTER TABLE public.site_contact_messages ADD COLUMN IF NOT EXISTS read_at timestamptz; CREATE INDEX IF NOT EXISTS site_contact_messages_creator_unread ON public.site_contact_messages (creator_id, created_at DESC) WHERE read_at IS NULL; END IF; END $$;
notify pgrst, 'reload schema';
